    ('bd3b50f1e07389496ba4bb01186dadadeaf2b72c5a68e793b7cbeefd78c9321a', 4, 'top100:bd3b50f1e07389496ba4bb01186dadadeaf2b72c5a68e793b7cbeefd78c9321a'),
    ('crux-solver.near', 4, 'top100:crux-solver.near')
